package ts

import (
	"github.com/SamuelTissot/sqltime"
	"github.com/github/turboscan/ts/proto"
	"github.com/google/uuid"
	"github.com/pkg/errors"
)

// LogicalAlertsSeqTableName defines a table name that will hold the sequences for
// the logical alerts table.  A sequence is generated by each repository_id
var LogicalAlertsSeqTableName = "ts_logical_alerts_seq"

// LogicalAlertID represents the ID used within a LogicalAlert
type LogicalAlertID uint64

// A LogicalAlert represents several physical alerts
type LogicalAlert struct {
	BaseModel
	ID                    LogicalAlertID `verify:"ignore"`
	RepositoryID          RepositoryEID
	Number                uint32
	RuleID                RuleID `verify:"ignore"`
	SarifIdentifier       string
	Resolution            AlertResolution
	ResolutionNote        Note
	ResolverID            *UserEID `verify:"ignore"`
	ResolvedAt            *sqltime.Time
	Weight                uint16
	StableAlertIdentifier []byte
	SeverityLevel         SeverityLevel
	SecuritySeverity      *float64 `verify:"ignore"`
	GUID                  string
	DismissalApproverID   *uint64 `verify:"ignore"`

	// De-normalised physical alert fields

	FilePath        string
	Region          Region `gorm:"EMBEDDED"`
	Message         string
	MessageMarkdown string

	FileClassification     FileClassification `verify:"ignore"` // JSON
	DefaultConfigurationID ConfigurationID    `verify:"ignore"`

	// Associations
	PhysicalAlerts         []*PhysicalAlert
	Rule                   *Rule
	Links                  []*AlertLink
	SuggestedFixAlert      *SuggestedFixAlert `gorm:"-" verify:"ignore"`
	SecurityCampaignAlerts []*SecurityCampaignAlert

	// Whether the logical alert is fixed is derived from the associated
	// physical alerts for the given configuration.
	IsFixed *bool `gorm:"-"`

	// The creation time of the analysis that last fixed an instance of the alert
	// Use GetFixedAt() to access, this is only public for GORM.
	LastObservedFixAt   *sqltime.Time `gorm:"-"`
	LastSeenAnalysisIDs string        `gorm:"-" verify:"ignore"`

	// The last user facing state change of a logical alert
	// This is only populated by the BuildLogicalAlertsQuery
	LastStateChangeAt *sqltime.Time `gorm:"-"`

	// To be able to see brand new logical alerts when processing
	// we record the analysis id of where this was first seen.
	// This is currently only set when processing, but we
	// may later decide to persist it in the database
	FirstSeenAnalysisID AnalysisID `gorm:"-" verify:"ignore"`

	// Autofix metadata
	AutofixEligible bool `gorm:"-" verify:"ignore"`

	// The configuration that the latest instance information is derived from
	DefaultConfiguration *Configuration `verify:"ignore"`
}

// GetFixedAt returns the date the last instance of this alert was fixed, or
// nil if the alert is not fixed
func (la *LogicalAlert) GetFixedAt() *sqltime.Time {
	if la.IsFixed != nil && *la.IsFixed {
		return la.LastObservedFixAt
	}
	return nil
}

// Canonical returns the canonical physical alert for a logical alert.
// Note: this is currently just a workaround until we change the API
// to accept multiple locations for each logical alert.
func (la *LogicalAlert) Canonical() (*PhysicalAlert, error) {
	if len(la.PhysicalAlerts) == 0 {
		return nil, errors.Errorf("no physical alerts found for logical alert %v", la.ID)
	}
	return la.PhysicalAlerts[0], nil
}

// SecuritySeverityLevel returns the securitySeverity mapped into
// a SecuritySeverityLevel enum value
func (la *LogicalAlert) SecuritySeverityLevel() proto.SecuritySeverity {
	return getSecuritySeverityLevel(la.SecuritySeverity)
}

// NewLogicalAlertGUID returns a fresh GUID
func NewLogicalAlertGUID() (string, error) {
	uuid, err := uuid.NewRandom()
	if err != nil {
		return "", err
	}
	return uuid.String(), nil
}

type Note string280

func ToNote(s string) Note {
	return Note(toString280(s))
}

func (n Note) String() string {
	return string(n)
}
